-- Fixture database for the integration tests.
--
-- Deliberately awkward in places: a quoted mixed-case schema, a table name
-- with a space, a composite foreign key, a self-reference, a partitioned
-- table, a materialised view and a generated column. Anything that only
-- works on well-behaved identifiers will fail here.

CREATE SCHEMA IF NOT EXISTS inventory;
CREATE SCHEMA IF NOT EXISTS "Reporting";

COMMENT ON SCHEMA inventory IS 'Stock and catalogue data.';

CREATE TABLE customers (
  id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  email text NOT NULL UNIQUE,
  display_name text,
  referred_by bigint REFERENCES customers (id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT customers_email_lowercase CHECK (email = lower(email))
);

COMMENT ON TABLE customers IS 'People who have placed an order.';
COMMENT ON COLUMN customers.email IS 'Lower case, unique.';

CREATE TABLE inventory.products (
  sku text PRIMARY KEY,
  title text NOT NULL,
  price_pence integer NOT NULL CHECK (price_pence >= 0),
  price_pounds numeric GENERATED ALWAYS AS (price_pence / 100.0) STORED,
  tags text[] NOT NULL DEFAULT '{}'
);

CREATE INDEX products_title_idx ON inventory.products USING btree (title);

CREATE TABLE orders (
  id bigserial PRIMARY KEY,
  customer_id bigint NOT NULL REFERENCES customers (id) ON DELETE RESTRICT
    ON UPDATE CASCADE,
  placed_at timestamptz NOT NULL DEFAULT now(),
  total_pence integer NOT NULL DEFAULT 0
);

CREATE TABLE order_lines (
  order_id bigint NOT NULL REFERENCES orders (id) ON DELETE CASCADE,
  line_no integer NOT NULL,
  sku text NOT NULL REFERENCES inventory.products (sku),
  quantity integer NOT NULL CHECK (quantity > 0),
  PRIMARY KEY (order_id, line_no)
);

-- A composite foreign key, so the relationship report has to keep column
-- order rather than joining on a single attribute.
CREATE TABLE shipments (
  order_id bigint NOT NULL,
  line_no integer NOT NULL,
  dispatched_at timestamptz,
  CONSTRAINT shipments_line_fk FOREIGN KEY (order_id, line_no)
    REFERENCES order_lines (order_id, line_no) ON DELETE CASCADE
);

CREATE TABLE "Reporting"."Daily Totals" (
  "Day" date PRIMARY KEY,
  "Total Pence" bigint NOT NULL
);

CREATE VIEW customer_orders AS
  SELECT c.id AS customer_id, c.email, count(o.id) AS orders
    FROM customers c LEFT JOIN orders o ON o.customer_id = c.id
   GROUP BY c.id, c.email;

CREATE MATERIALIZED VIEW popular_products AS
  SELECT sku, sum(quantity) AS sold FROM order_lines GROUP BY sku;

CREATE TABLE events (
  id bigint GENERATED BY DEFAULT AS IDENTITY,
  occurred_on date NOT NULL,
  payload jsonb
) PARTITION BY RANGE (occurred_on);

CREATE TABLE events_2026 PARTITION OF events
  FOR VALUES FROM ('2026-01-01') TO ('2027-01-01');

CREATE SEQUENCE inventory.restock_seq START 100 INCREMENT 5;

